@if(auth()->user()->isAdmin())
<script>
// Semua mutasi memakai FormData dan JSON; daftar tabel diperbarui tanpa reload.
const facilityModal=new bootstrap.Modal('#facility-modal'),facilityForm=document.getElementById('facility-form');
function resetFacility(){facilityForm.reset();facilityForm.action='{{ route('facilities.store') }}';facilityForm.querySelector('.modal-title').textContent='Tambah fasilitas';$('#facility-errors').addClass('d-none').empty()}
function renderFacility(f){let row=document.getElementById('facility-'+f.id);if(!row){$('#empty-facility').remove();row=document.createElement('tr');row.id='facility-'+f.id;row.innerHTML='<td class="fw-semibold"></td><td></td><td></td><td></td><td class="text-end"><button class="btn btn-sm btn-outline-primary edit-facility">Ubah</button> <button class="btn btn-sm btn-outline-danger delete-facility">Hapus</button></td>';document.getElementById('facility-rows').prepend(row)}row.dataset.id=f.id;row.dataset.name=f.name;row.dataset.location=f.location;row.dataset.category=f.category;row.dataset.description=f.description||'';row.dataset.condition=f.condition;row.children[0].textContent=f.name;row.children[1].textContent=f.location;row.children[2].textContent=f.category;row.children[3].innerHTML='';const badge=document.createElement('span');badge.className='badge text-bg-'+(f.condition==='baik'?'success':'warning');badge.textContent=f.condition.replaceAll('_',' ');row.children[3].append(badge);row.querySelector('.delete-facility').dataset.url='/facilities/'+f.id}
$('#add-facility').on('click',()=>{resetFacility();facilityModal.show()});
$(document).on('click','.edit-facility',function(){const row=this.closest('tr');resetFacility();facilityForm.action='/facilities/'+row.dataset.id;facilityForm.querySelector('.modal-title').textContent='Ubah fasilitas';for(const key of ['name','location','category','description','condition'])facilityForm.elements.namedItem(key).value=row.dataset[key]||'';facilityModal.show()});
$('#facility-form').on('submit',async function(e){e.preventDefault();const fd=new FormData(this);if(this.action.includes('/facilities/'))fd.append('_method','PUT');showLoading(true);$('#save-facility').prop('disabled',true);try{const response=await fetch(this.action,{method:'POST',body:fd,headers:{Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content}});const data=await response.json();if(!response.ok){const errors=data.errors?Object.values(data.errors).flat().join(' '):(data.message||'Data tidak dapat disimpan.');$('#facility-errors').removeClass('d-none').text(errors);return}renderFacility(data.facility);notify(data.message);facilityModal.hide()}catch(error){notify('Koneksi ke server gagal.','danger')}finally{showLoading(false);$('#save-facility').prop('disabled',false)}});
$(document).on('click','.delete-facility',async function(){if(!confirm('Hapus fasilitas ini?'))return;showLoading(true);try{const response=await fetch(this.dataset.url,{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Content-Type':'application/x-www-form-urlencoded'},body:'_method=DELETE'});const data=await response.json();if(!response.ok)throw Error(data.message);this.closest('tr').remove();notify(data.message)}catch(error){notify(error.message||'Gagal menghapus.','danger')}finally{showLoading(false)}});
</script>
@endif
@endpush
